from .common_oam import CoamSelenium
from moler.exceptions import ExecutionException


class Selenium(object):

    oam_type = None

    def __new__(cls, gnb_class_object=None, oam_type='MZOAM', *args, **kwargs):

        if Selenium.oam_type is None:
            if gnb_class_object is None:
                try:
                    Selenium.oam_type = Selenium._get_oam_type_from_airscale()
                except ExecutionException:
                    Selenium.oam_type = oam_type
            else:
                Selenium.oam_type = gnb_class_object.oam_type

        instance = super(Selenium, cls).__new__(Selenium._get_oam_class_name())

        if hasattr(cls, '__init__'):
            instance.__init__(*args, **kwargs)

        return instance

    @staticmethod
    def _get_oam_type_from_airscale():
        from taf.ul.sc.gnb.airscale import AirScale
        return AirScale(autoconnect=True).oam_type

    @staticmethod
    def _get_oam_class_name():
        if Selenium.oam_type == 'MZOAM':
            raise NotImplementedError("MZSelenium is not supported anymore")
        else:
            return CoamSelenium


__all__ = ['Selenium']
